<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { productApi, type ProductDetailVO, type ProductListVO } from '@/api/product'
import { presaleApi, type PresaleActivity, type PresaleSku } from '@/api/presale'

const loading = ref(false); const saving = ref(false); const dialog = ref(false); const editingId = ref<number | null>(null)
const list = ref<PresaleActivity[]>([]); const products = ref<ProductListVO[]>([])
const emptySku = (): PresaleSku => ({ productId: null, skuId: null, finalPrice: null, depositAmount: null, depositDeductionAmount: null, userLimit: 1, skuOptions: [] })
const empty = (): PresaleActivity => ({ activityName: '', description: '', bannerImage: '', depositStartAt: '', depositEndAt: '', balanceStartAt: '', balanceEndAt: '', expectedShipAt: '', autoCloseExpired: 1, depositRefundRule: '尾款支付前可申请退还定金；商家未按期发货时全额退款。', merchantBreachRule: '商家未按预计时间发货时，用户可申请全额退款。', skus: [emptySku()] })
const form = ref<PresaleActivity>(empty())

async function load() { loading.value = true; try { const [page, productPage] = await Promise.all([presaleApi.page({ page: 1, size: 50 }), productApi.page({ page: 1, size: 200, status: 1, auditStatus: 1 })]); list.value = page?.list || []; products.value = productPage?.list || [] } finally { loading.value = false } }
function openCreate() { editingId.value = null; form.value = empty(); dialog.value = true }
async function openEdit(row: { id?: number }) { if (!row.id) return; const detail = await presaleApi.get(row.id); form.value = { ...detail, activityName: detail.name, skus: (detail.skus || []).map((item) => ({ ...item, skuOptions: [] })) }; await Promise.all(form.value.skus.map((item) => loadSkuOptions(item, false))); editingId.value = row.id; dialog.value = true }
async function loadSkuOptions(item: PresaleSku, reset = true) { if (!item.productId) { item.skuId = null; item.skuOptions = []; return }; const detail: ProductDetailVO = await productApi.get(Number(item.productId)); item.skuOptions = (detail.skus || []).map((sku) => ({ id: sku.id, specText: sku.specText, price: sku.price, stock: sku.stock })); if (reset) item.skuId = null }
function addSku() { form.value.skus.push(emptySku()) }
function removeSku(index: number) { if (form.value.skus.length > 1) form.value.skus.splice(index, 1) }
function selectedSku(item: PresaleSku) { return (item.skuOptions || []).find((sku) => sku.id === item.skuId) }
function validate() { const f = form.value; if (!f.activityName?.trim() || !f.depositStartAt || !f.depositEndAt || !f.balanceStartAt || !f.balanceEndAt || !f.expectedShipAt) return '请完整填写活动名称和时间'; if (!(new Date(f.depositStartAt) < new Date(f.depositEndAt) && new Date(f.depositEndAt) < new Date(f.balanceStartAt) && new Date(f.balanceStartAt) < new Date(f.balanceEndAt) && new Date(f.expectedShipAt) >= new Date(f.balanceEndAt))) return '时间顺序应为：定金开始 < 定金结束 < 尾款开始 < 尾款结束 ≤ 预计发货'; for (const item of f.skus) { const sku = selectedSku(item); const finalPrice = Number(item.finalPrice || 0) || Number(item.balanceAmount || 0) + Number(item.depositDeductionAmount || 0); if (!item.productId || !item.skuId || !sku || !finalPrice || !item.depositAmount || !item.depositDeductionAmount || !item.userLimit) return '请完整填写商品、SKU、金额和限购'; if (finalPrice <= Number(item.depositDeductionAmount)) return '最终价必须高于定金抵扣金额' }; return '' }
async function save() { const message = validate(); if (message) return ElMessage.warning(message); saving.value = true; try { const { id, name, status, statusText, phaseText, ...activityFields } = form.value; const payload = { ...activityFields, skus: form.value.skus.map(({ id: skuId, skuOptions, productName, mainImage, specText, originalPrice, finalAmount, stock, depositCount, balanceSoldCount, ...item }) => ({ ...item, finalPrice: Number(item.finalPrice || 0) || Number(item.balanceAmount || 0) + Number(item.depositDeductionAmount || 0) })) } as PresaleActivity; if (editingId.value) await presaleApi.update(editingId.value, payload); else await presaleApi.create(payload); ElMessage.success(editingId.value ? '预售活动已更新' : '预售活动已发布'); dialog.value = false; await load() } finally { saving.value = false } }
async function edit(row: { id?: number }) { try { await ElMessageBox.confirm('活动开始后核心规则不可修改，请确认当前活动尚未开始。', '编辑预售活动', { type: 'warning' }); await openEdit(row) } catch {} }
function time(row: { depositStartAt?: string; balanceEndAt?: string }) { return `${row.depositStartAt || '-'} 至 ${row.balanceEndAt || '-'}` }
onMounted(load)
</script>

<template>
  <div class="presale-page page">
    <div class="page-header"><div><span class="page-kicker">PRESALE DEPOSIT INFLATION</span><h1 class="page-title">预售定金膨胀</h1><p class="page-desc">先收定金锁定需求，尾款支付成功后才校验并扣减可发货库存，禁止与其他营销活动叠加。</p></div><div class="page-actions"><el-button @click="load">刷新</el-button><el-button type="primary" @click="openCreate">新建预售</el-button></div></div>
    <el-alert title="活动边界" description="定金只锁定需求，不占用库存；尾款逾期可自动关闭并退定金，也可进入待处理由商家人工处理。活动开始后核心规则锁定。" type="info" show-icon :closable="false" class="tip" />
    <el-table v-loading="loading" :data="list" class="activity-table"><el-table-column prop="name" label="活动名称" min-width="180" /><el-table-column label="状态" width="110"><template #default="{ row }"><el-tag :type="row.status === 1 ? 'success' : 'info'">{{ row.statusText }}</el-tag></template></el-table-column><el-table-column label="阶段" width="110"><template #default="{ row }">{{ row.phaseText }}</template></el-table-column><el-table-column label="时间" min-width="280"><template #default="{ row }">{{ time(row) }}</template></el-table-column><el-table-column label="SKU" width="80"><template #default="{ row }">{{ row.skus?.length || 0 }}</template></el-table-column><el-table-column label="操作" width="160"><template #default="{ row }"><el-button link type="primary" @click="edit(row)">编辑</el-button><el-button link type="primary" @click="row.id && presaleApi.stats(row.id).then((s) => ElMessage.info(`定金订单 ${s.depositOrderCount}，尾款支付 ${s.balancePaidOrderCount}，成交 ¥${s.finalAmount}`))">统计</el-button></template></el-table-column></el-table>
    <el-dialog v-model="dialog" :title="editingId ? '编辑预售活动' : '新建预售活动'" width="980px" top="4vh"><el-form label-width="120px"><el-form-item label="活动名称"><el-input v-model="form.activityName" maxlength="128" placeholder="如：新品耳机预售" /></el-form-item><el-form-item label="活动说明"><el-input v-model="form.description" maxlength="500" placeholder="展示在小程序会场顶部" /></el-form-item><el-form-item label="定金时间"><el-date-picker v-model="form.depositStartAt" type="datetime" value-format="YYYY-MM-DD HH:mm:ss" placeholder="开始" /><span class="to">至</span><el-date-picker v-model="form.depositEndAt" type="datetime" value-format="YYYY-MM-DD HH:mm:ss" placeholder="结束" /></el-form-item><el-form-item label="尾款时间"><el-date-picker v-model="form.balanceStartAt" type="datetime" value-format="YYYY-MM-DD HH:mm:ss" placeholder="开始" /><span class="to">至</span><el-date-picker v-model="form.balanceEndAt" type="datetime" value-format="YYYY-MM-DD HH:mm:ss" placeholder="结束" /></el-form-item><el-form-item label="预计发货"><el-date-picker v-model="form.expectedShipAt" type="datetime" value-format="YYYY-MM-DD HH:mm:ss" /></el-form-item><el-form-item label="逾期处理"><el-switch v-model="form.autoCloseExpired" :active-value="1" :inactive-value="0" active-text="自动关闭并退定金" inactive-text="进入待处理" /></el-form-item><el-form-item label="定金退款规则"><el-input v-model="form.depositRefundRule" type="textarea" :rows="2" /></el-form-item><el-form-item label="商家违约规则"><el-input v-model="form.merchantBreachRule" type="textarea" :rows="2" /></el-form-item><div v-for="(item, index) in form.skus" :key="index" class="sku-editor"><div class="sku-head"><strong>预售 SKU {{ index + 1 }}</strong><el-button v-if="form.skus.length > 1" link type="danger" @click="removeSku(index)">移除</el-button></div><div class="sku-grid"><el-select v-model="item.productId" filterable placeholder="选择商品" @change="loadSkuOptions(item)"><el-option v-for="product in products" :key="product.id" :label="product.name" :value="product.id" /></el-select><el-select v-model="item.skuId" placeholder="选择规格" :disabled="!item.skuOptions?.length"><el-option v-for="sku in item.skuOptions" :key="sku.id" :label="`${sku.specText || '默认规格'} · ¥${sku.price} · 库存${sku.stock}`" :value="sku.id" /></el-select><el-input-number v-model="item.depositAmount" :min="0.01" :precision="2" controls-position="right" placeholder="定金" /><el-input-number v-model="item.depositDeductionAmount" :min="0.01" :precision="2" controls-position="right" placeholder="抵扣" /><el-input-number v-model="item.balanceAmount" :min="0.01" :precision="2" controls-position="right" placeholder="尾款" /><el-input-number v-model="item.userLimit" :min="1" :max="999" :precision="0" controls-position="right" placeholder="限购" /></div><div class="sku-hint">示例：定金 ¥20，抵扣 ¥60，尾款 ¥399，最终实付 ¥419；不占用当前库存。</div></div><el-button class="add-sku" @click="addSku">+ 添加 SKU</el-button></el-form><template #footer><el-button @click="dialog = false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存并发布</el-button></template></el-dialog>
  </div>
</template>

<style scoped>
.tip { margin-bottom: 18px; }.activity-table { border-radius: 16px; overflow: hidden; }.to { margin: 0 10px; color: var(--shop-muted); }.sku-editor { margin: 18px 0; padding: 16px; border: 1px solid var(--shop-line); border-radius: 14px; background: #fffaf5; }.sku-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 12px; }.sku-grid { display: grid; grid-template-columns: 1.2fr 1.5fr repeat(4, 120px); gap: 8px; align-items: center; }.sku-grid :deep(.el-input-number) { width: 100%; }.sku-hint { margin-top: 8px; color: var(--shop-muted); font-size: 12px; }.add-sku { width: 100%; border-style: dashed; }@media (max-width: 900px) { .sku-grid { grid-template-columns: 1fr 1fr; } }
</style>
